{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.customer_acq_date_channel as WITH online_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'Shopify\' AS store, MIN(order_timestamp) AS online_acq FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1 ), offline_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped AS store, order_timestamp AS offline_acq FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' QUALIFY ROW_NUMBER() OVER (PARTITION BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) ORDER BY order_timestamp ASC) = 1 ), online_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(gross_sales) AS online_sales FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1 ), offline_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(selling_price) as offline_sales FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' group by 1 ), combined_acq AS ( SELECT phone_no, online_acq AS order_date, store FROM online_acq UNION ALL SELECT phone_no, offline_acq AS order_date, store FROM offline_acq ), final_check as ( SELECT phone_no, order_date::date AS first_order_date, store FROM combined_acq qualify row_number() over (partition by phone_no order by order_date asc) = 1 ) select a.*, ifnull(online_sales,0) as online_sales, ifnull(offline_sales,0) as offline_sales, case when ifnull(online_sales,0)>= ifnull(offline_sales,0) then \'Shopify\' else \'Stores\' end as customer_main_channel from final_check a left join online_sales b on a.phone_no = b.phone_no left join offline_sales c on a.phone_no = c.phone_no where length(a.phone_no) = 13 and a.phone_no not in (\'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\',\'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\') ; create or replace table snitch_db.maplemonk.retention_online as WITH total_data AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, LEFT(DATE_TRUNC(month, order_timestamp), 10) AS Month, CASE WHEN Pincode LIKE \'11%\' THEN \'Delhi\' WHEN Pincode LIKE \'12%\' OR Pincode LIKE \'13%\' THEN \'Haryana\' WHEN Pincode LIKE \'14%\' OR Pincode LIKE \'15%\' THEN \'Punjab\' WHEN Pincode LIKE \'16%\' THEN \'Chandigarh\' WHEN Pincode LIKE \'17%\' THEN \'Himachal Pradesh\' WHEN Pincode LIKE \'18%\' OR Pincode LIKE \'19%\' THEN \'Jammu and Kashmir, Ladakh\' WHEN Pincode BETWEEN \'200000\' AND \'289999\' THEN \'Uttar Pradesh, Uttarakhand\' WHEN Pincode BETWEEN \'300000\' AND \'349999\' THEN \'Rajasthan\' WHEN Pincode BETWEEN \'360000\' AND \'399999\' AND Pincode NOT LIKE \'396%\' THEN \'Gujarat\' WHEN Pincode LIKE \'396%\' THEN \'Dadra & Nagar Haveli and Daman & Diu\' WHEN Pincode BETWEEN \'400000\' AND \'449999\' AND Pincode NOT LIKE \'403%\' THEN \'Maharashtra\' WHEN Pincode LIKE \'403%\' THEN \'Goa\' WHEN Pincode BETWEEN \'450000\' AND \'489999\' THEN \'Madhya Pradesh\' WHEN Pincode LIKE \'49%\' THEN \'Chhattisgarh\' WHEN Pincode LIKE \'50%\' THEN \'Telangana\' WHEN Pincode BETWEEN \'510000\' AND \'539999\' THEN \'Andhra Pradesh\' WHEN Pincode BETWEEN \'560000\' AND \'599999\' THEN \'Karnataka\' WHEN Pincode BETWEEN \'600000\' AND \'669999\' THEN \'Tamil Nadu\' WHEN Pincode LIKE \'605%\' THEN \'Puducherry\' WHEN Pincode BETWEEN \'670000\' AND \'699999\' AND Pincode NOT LIKE \'682%\' THEN \'Kerala\' WHEN Pincode LIKE \'682%\' THEN \'Lakshadweep\' WHEN Pincode BETWEEN \'700000\' AND \'749999\' AND Pincode NOT LIKE \'737%\' AND Pincode NOT LIKE \'744%\' THEN \'West Bengal\' WHEN Pincode LIKE \'737%\' THEN \'Sikkim\' WHEN Pincode LIKE \'744%\' THEN \'Andaman and Nicobar Islands\' WHEN Pincode BETWEEN \'750000\' AND \'779999\' THEN \'Odisha\' WHEN Pincode LIKE \'78%\' THEN \'Assam\' WHEN Pincode BETWEEN \'790000\' AND \'799999\' THEN \'Arunachal Pradesh\' WHEN Pincode BETWEEN \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN Pincode LIKE \'795%\' THEN \'Manipur\' WHEN Pincode LIKE \'796%\' THEN \'Mizoram\' WHEN Pincode BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN Pincode LIKE \'799%\' THEN \'Tripura\' WHEN Pincode BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN Pincode BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS state, SUM(gross_sales) AS total_revenue, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.fact_items_snitch WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1, 2, 3 ), agg_total_data AS ( SELECT phone_no, state, month, SUM(total_revenue) AS total_revenue, SUM(total_orders) AS total_orders FROM total_data GROUP BY 1, 2, 3 ), acqmonth AS ( SELECT phone_no, cast(MIN(month) as date) AS acqmonth FROM agg_total_data GROUP BY 1 ), combined_data AS ( SELECT a.*, b.acqmonth, DATEDIFF(\'month\', b.acqmonth, a.month) AS month_diff FROM agg_total_data a LEFT JOIN acqmonth b ON a.phone_no = b.phone_no ), acquisition_stats AS ( SELECT acqmonth, state as acq_state, COUNT(DISTINCT phone_no) AS customers_acquired, SUM(total_revenue) as revenue_acquired, SUM(total_orders) as order_acquired FROM combined_data where month_diff = 0 GROUP BY 1,2 ), retention_stats AS ( SELECT acqmonth,state, COUNT(DISTINCT CASE WHEN month_diff = 1 THEN phone_no END) AS retained_1_month, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 3 THEN phone_no END) AS retained_3_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 4 THEN phone_no END) AS retained_4_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 6 THEN phone_no END) AS retained_6_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 12 THEN phone_no END) AS retained_12_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 18 THEN phone_no END) AS retained_18_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 24 THEN phone_no END) AS retained_24_months, sum(CASE WHEN month_diff BETWEEN 1 AND 12 THEN total_revenue end) as retained_12_month_revenue, sum(CASE WHEN month_diff BETWEEN 1 AND 12 THEN total_orders end) as retained_12_month_orders FROM combined_data GROUP BY 1,2 ) SELECT a.acqmonth, a.customers_acquired, a.acq_state, a.revenue_acquired, a.order_acquired, r.retained_1_month, r.retained_3_months, r.retained_4_months, r.retained_6_months, r.retained_12_months, r.retained_18_months, r.retained_24_months, r.retained_12_month_revenue, r.retained_12_month_orders FROM acquisition_stats a LEFT JOIN retention_stats r ON a.acqmonth = r.acqmonth and a.acq_state = r.state ORDER BY a.acqmonth ; create or replace table snitch_db.maplemonk.region_wise_sessions_retention as with sessions as ( select TO_DATE(DATE, \'YYYYMMDD\') AS date, \'Web\' as type, region as state, sum(sessions) as sessions from snitch_db.maplemonk.web_region_wise_sessions where state in (\'Maharashtra\', \'Uttar Pradesh\',\'Karnataka\',\'Delhi\',\'Telangana\',\'Gujarat\',\'Rajasthan\',\'Bihar\',\'Tamil Nadu\',\'West Bengal\',\'Madhya Pradesh\',\'Haryana\',\'Odisha\',\'Kerala\',\'Assam\',\'Andhra Pradesh\',\'Punjab\',\'Jammu and Kashmir\',\'Jharkhand\',\'Chhattisgarh\',\'Tripura\',\'Himachal Pradesh\',\'Uttarakhand\',\'Goa\',\'Nagaland\',\'Meghalaya\',\'Mizoram\',\'Andaman and Nicobar Islands\',\'Manipur\',\'Dadra and Nagar Haveli and Daman and Diu\',\'Puducherry\',\'Sikkim\',\'Arunachal Pradesh\') group by 1,2,3 union select TO_DATE(DATE, \'YYYYMMDD\') AS date, \'android\' as type, region as state, sum(sessions) as sessions from snitch_db.maplemonk.region_wise_sessions_app2 where state in (\'Maharashtra\', \'Uttar Pradesh\',\'Karnataka\',\'Delhi\',\'Telangana\',\'Gujarat\',\'Rajasthan\',\'Bihar\',\'Tamil Nadu\',\'West Bengal\',\'Madhya Pradesh\',\'Haryana\',\'Odisha\',\'Kerala\',\'Assam\',\'Andhra Pradesh\',\'Punjab\',\'Jammu and Kashmir\',\'Jharkhand\',\'Chhattisgarh\',\'Tripura\',\'Himachal Pradesh\',\'Uttarakhand\',\'Goa\',\'Nagaland\',\'Meghalaya\',\'Mizoram\',\'Andaman and Nicobar Islands\',\'Manipur\',\'Dadra and Nagar Haveli and Daman and Diu\',\'Puducherry\',\'Sikkim\',\'Arunachal Pradesh\') and lower(operatingsystem) = \'android\' group by 1,2,3 union select TO_DATE(DATE, \'YYYYMMDD\') AS date, \'IOS\' as type, region as state, sum(sessions) as sessions from snitch_db.maplemonk.region_wise_sessions_app2 where state in (\'Maharashtra\', \'Uttar Pradesh\',\'Karnataka\',\'Delhi\',\'Telangana\',\'Gujarat\',\'Rajasthan\',\'Bihar\',\'Tamil Nadu\',\'West Bengal\',\'Madhya Pradesh\',\'Haryana\',\'Odisha\',\'Kerala\',\'Assam\',\'Andhra Pradesh\',\'Punjab\',\'Jammu and Kashmir\',\'Jharkhand\',\'Chhattisgarh\',\'Tripura\',\'Himachal Pradesh\',\'Uttarakhand\',\'Goa\',\'Nagaland\',\'Meghalaya\',\'Mizoram\',\'Andaman and Nicobar Islands\',\'Manipur\',\'Dadra and Nagar Haveli and Daman and Diu\',\'Puducherry\',\'Sikkim\',\'Arunachal Pradesh\') and lower(operatingsystem) = \'ios\' group by 1,2,3 ) select * from sessions ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.CUSTOMER_RETENTION_BY_PURCHASE_DATE_UPDATED AS WITH InitialResult AS ( SELECT customer_id_final, last_day(order_date) as order_month, sum(selling_price) as sales FROM snitch_db.snitch.ORDERS_fact where SOURCE_CHANNEL = \'SHOPIFY\' group by 1,2 ), combineResult AS( select ori.*,date1 from InitialResult ori left join (select customer_id_final, order_month as date1 from InitialResult)dup on ori.customer_id_final = dup.customer_id_final ) select c.*, cm.phone, cm.email, datediff(\'month\',order_month,date1) as next_month, 0.65 as gross_margin from combineResult c left join (select customer_id_final as cid,phone,email from snitch_db.snitch.customer_dim) as cm on cm.cid = c.customer_id_final where next_month >=0 ; create or replace table snitch_db.maplemonk.retention_online_offline as WITH online_total_data AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, LEFT(DATE_TRUNC(month, order_timestamp), 10) AS Month, SUM(gross_sales) AS total_revenue, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.fact_items_snitch WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1, 2 ), offline_total_data as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, LEFT(DATE_TRUNC(month, order_date), 10) AS Month, SUM(selling_price) AS total_revenue, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) not LIKE \'%wh%\' GROUP BY 1,2 ), total_data as ( select * from online_total_data union all select * from offline_total_data ), agg_total_data AS ( SELECT phone_no, month, SUM(total_revenue) AS total_revenue, SUM(total_orders) AS total_orders FROM total_data GROUP BY 1, 2 ), acqmonth AS ( SELECT phone_no, cast(MIN(month) as date) AS acqmonth FROM agg_total_data GROUP BY 1 ), combined_data AS ( SELECT a.*, b.acqmonth, DATEDIFF(\'month\', b.acqmonth, a.month) AS month_diff, c.store FROM agg_total_data a LEFT JOIN acqmonth b ON a.phone_no = b.phone_no left join snitch_db.maplemonk.customer_acq_date_channel c on a.phone_no = c.phone_no ), acquisition_stats AS ( SELECT acqmonth, store as acq_channel, COUNT(DISTINCT phone_no) AS customers_acquired, SUM(total_revenue) as revenue_acquired, SUM(total_orders) as order_acquired FROM combined_data where month_diff = 0 GROUP BY 1,2 ), retention_stats AS ( SELECT acqmonth, store as acq_channel, COUNT(DISTINCT CASE WHEN month_diff = 1 THEN phone_no END) AS retained_1_month, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 3 THEN phone_no END) AS retained_3_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 4 THEN phone_no END) AS retained_4_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 6 THEN phone_no END) AS retained_6_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 12 THEN phone_no END) AS retained_12_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 18 THEN phone_no END) AS retained_18_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 24 THEN phone_no END) AS retained_24_months, sum(CASE WHEN month_diff BETWEEN 1 AND 12 THEN total_revenue end) as retained_12_month_revenue, sum(CASE WHEN month_diff BETWEEN 1 AND 12 THEN total_orders end) as retained_12_month_orders FROM combined_data GROUP BY 1,2 ) SELECT a.acqmonth, a.customers_acquired, a.revenue_acquired, a.order_acquired, r.retained_1_month, r.retained_3_months, r.retained_4_months, r.retained_6_months, r.retained_12_months, r.retained_18_months, r.retained_24_months, r.retained_12_month_revenue, r.retained_12_month_orders, a.acq_channel FROM acquisition_stats a LEFT JOIN retention_stats r ON a.acqmonth = r.acqmonth and a.acq_channel = r.acq_channel ORDER BY a.acqmonth ; create or replace table snitch_db.maplemonk.category_retention_online_offline as ( with cat_total_data as ( select \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_name, order_timestamp::date as order_date, upper(trim(sku_group)) as sku_group, sum(gross_sales) as total_revenue, FROM snitch_db.maplemonk.fact_items_snitch a WHERE LOWER(IFNULL(a.discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(a.discount_code, \'n\')) NOT LIKE \'%influ%\' AND a.order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND a.tags NOT IN (\'FLITS_LOGICERP\') group by 1,2,3,4 union all SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_name, order_date, upper(trim(sku_group)) as sku_group, sum(selling_price) as total_revenue FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) not LIKE \'%wh%\' and lower(sku_group) not like \'%bp%\' GROUP BY 1,2,3,4 ), first_order_details as ( select phone_no, order_name, row_number() over (partition by phone_no order by order_date asc) as rn from cat_total_data ), acq_category as ( select a.phone_no, b.category from cat_total_data a left join snitch_db.maplemonk.availability_master_v2 b on upper(trim(a.sku_group)) = upper(trim(b.sku_group)) where order_name in (select order_name from first_order_details where rn = 1) and (b.category is not null or b.category != \'\') ), online_total_data AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, LEFT(DATE_TRUNC(month, order_timestamp), 10) AS Month, SUM(gross_sales) AS total_revenue, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.fact_items_snitch WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1, 2 ), offline_total_data as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, LEFT(DATE_TRUNC(month, order_date), 10) AS Month, SUM(selling_price) AS total_revenue, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) not LIKE \'%wh%\' GROUP BY 1,2 ), total_data as ( select * from online_total_data union all select * from offline_total_data ), agg_total_data AS ( SELECT phone_no, month, SUM(total_revenue) AS total_revenue, SUM(total_orders) AS total_orders FROM total_data GROUP BY 1, 2 ), acqmonth AS ( SELECT a.phone_no, cast(MIN(a.month) as date) AS acqmonth, FROM agg_total_data a GROUP BY 1 ), combined_data AS ( SELECT a.*, b.acqmonth, c.category as acq_cat, DATEDIFF(\'month\', b.acqmonth, a.month) AS month_diff FROM agg_total_data a LEFT JOIN acqmonth b ON a.phone_no = b.phone_no left join acq_category c on a.phone_no = c.phone_no ) SELECT acqmonth, acq_cat, COUNT(DISTINCT CASE WHEN month_diff = 0 THEN phone_no END) AS customer_acq, COUNT(DISTINCT CASE WHEN month_diff = 1 THEN phone_no END) AS retained_1_month, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 3 THEN phone_no END) AS retained_3_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 4 THEN phone_no END) AS retained_4_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 6 THEN phone_no END) AS retained_6_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 12 THEN phone_no END) AS retained_12_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 18 THEN phone_no END) AS retained_18_months, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 1 AND 24 THEN phone_no END) AS retained_24_months FROM combined_data GROUP BY 1,2 ) ;",
